// ── seeded RNG (mulberry32) ─────────────────────────────────────────────────
function rngOf(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = rngOf(0xc10_4);
const pick = <T>(xs: ReadonlyArray<T>): T => xs[Math.floor(rng() * xs.length)];
const chance = (p: number) => rng() < p;
const int = (lo: number, hi: number) => lo + Math.floor(rng() * (hi - lo + 1));
function sample<T>(xs: ReadonlyArray<T>, n: number): T[] {
  const copy = [...xs];
  const out: T[] = [];
  while (out.length < n && copy.length > 0) out.push(copy.splice(Math.floor(rng() * copy.length), 1)[0]);
  return out;
}

// ── floats serde_json parses exactly ────────────────────────────────────────
function serdeExact(x: number): boolean {
  if (!Number.isFinite(x)) return false;
  if (Number.isInteger(x)) return Math.abs(x) <= 2 ** 53;
  const s = String(Math.abs(x));
  const [mant, expPart] = s.split("e");
  let exp = expPart ? parseInt(expPart, 10) : 0;
  const [ip, fp = ""] = mant.split(".");
  let digits = (ip + fp).replace(/^0+/, "");
  exp -= fp.length;
  while (digits.length > 1 && digits.endsWith("0")) {
    digits = digits.slice(0, -1);
    exp += 1;
  }
  if (digits === "") return true;
  return BigInt(digits) <= BigInt(2) ** BigInt(53) && Math.abs(exp) <= 22;
}
const f64 = new Float64Array(1);
const u64 = new BigUint64Array(f64.buffer);
function step(x: number, dir: 1 | -1): number {
  f64[0] = x;
  u64[0] = u64[0] + BigInt(dir); // positive finite x only
  return f64[0];
}
/** The nearest serde-exact value strictly on one side of `t`. */
function beside(t: number, dir: 1 | -1): number {
  let x = step(t, dir);
  for (let i = 0; i < 4096 && !serdeExact(x); i++) x = step(x, dir);
  if (!serdeExact(x)) throw new Error(`no exact value beside ${t}`);
  return x;
}
const EDGES = [0.3, 0.5, 0.7, 0.8, 0.85];
const INTERESTING: number[] = [
  0, 1, 0.05, 0.1, 0.2, 0.4, 0.6, 0.65, 0.75, 0.9, 0.95, 0.99,
  // toFixed(2) half-way and near-half-way cases.
  0.005, 0.015, 0.125, 0.375, 0.625, 0.875, 0.705, 0.715, 0.725, 0.735, 0.745, 0.755, 0.765, 0.775,
  0.785, 0.795, 0.805, 0.815, 0.825, 0.835, 0.845, 0.855, 0.865, 0.885, 0.895, 0.905, 0.915, 0.925,
  0.935, 0.945, 0.955, 0.965, 0.975, 0.985, 0.995,
  ...[0.995, 0.125, 0.845].flatMap((t) => [beside(t, -1), beside(t, 1)]),
  ...EDGES.flatMap((t) => [t, beside(t, -1), beside(t, 1)]),
];
for (const x of INTERESTING) if (!serdeExact(x)) throw new Error(`${x} is not serde-exact`);
const rand4 = () => Math.round(rng() * 1e4) / 1e4;
/** An answer value, biased by `lean`. */
function value(lean: "high" | "low" | "any"): number {
  if (chance(0.55)) {
    const pool =
      lean === "high" ? INTERESTING.filter((x) => x >= 0.65) : lean === "low" ? INTERESTING.filter((x) => x < 0.72) : INTERESTING;
    return pick(pool);
  }
  const x = rand4();
  return lean === "high" ? 0.6 + x * 0.4 : lean === "low" ? x * 0.75 : x;
}
const fix = (x: number) => (serdeExact(x) ? x : Math.round(x * 1e4) / 1e4);

