function synthDecl(i: number): any {
  const probes = Array.from({ length: int(1, chance(0.15) ? 6 : 3) }, (_, j) => ({
    id: j === 0 ? "does_it" : `p${j}_${pick(["x", "y", "z"])}`,
    instructions: pick(PROBE_TEXT),
    ...(chance(0.7) ? { criteria: { true: "Yes, clearly.", false: "No, or not clearly." } } : {}),
  }));
  const precondition = pick(PRECONDITIONS);
  const d: any = {
    name: `syn-${String(i).padStart(2, "0")}${pick(["", ".v2", "_x", "-check"])}`,
    title: pick(TITLES),
    appliesTo: sample(CLASSES, int(1, 3)),
    mode: chance(0.6) ? "deny" : "instruct",
    userCanOverride: chance(0.75),
    probes,
    guidance: pick(GUIDANCE),
  };
  if (chance(0.3)) d.exempt = { id: "ignored", instructions: "A documented exception applies (a scratch dir, a test fixture)." };
  if (chance(0.2)) d.exempt = { ...(d.exempt ?? { instructions: "It is a dry run." }), criteria: { true: "Exempt.", false: "Not exempt." } };
  if (precondition !== undefined) d.precondition = precondition;
  return d;
}
const RAW_DECLS = [...VALID, ...Array.from({ length: 40 }, (_, i) => synthDecl(i))];
const DECLS: any[] = RAW_DECLS.map((d, i) => (parseDecl ? parseDecl("cloud", d, i) : d));
const BY_NAME = new Map<string, any>(DECLS.map((d) => [d.name, d]));
if (BY_NAME.size !== DECLS.length) throw new Error("duplicate declaration names");

/** `toSemanticPolicy` in pack-policies.ts, minus `origin` (attribution only). */
function toPolicy(entry: any): any {
  const precondition = entry.precondition === undefined ? null : preconditionFor(entry.precondition);
  return {
    name: entry.name,
    title: entry.title,
    appliesTo: entry.appliesTo,
    mode: entry.mode,
    userCanOverride: entry.userCanOverride,
    probes: entry.probes,
    ...(entry.exempt ? { exempt: entry.exempt } : {}),
    ...(precondition ? { precondition } : {}),
    guidance: entry.guidance,
  };
}
const POLICIES = new Map<string, any>(DECLS.map((d) => [d.name, toPolicy(d)]));

