function toolInputOf(): { toolName: string; toolInput: Record<string, unknown> } {
  if (chance(0.62)) return { toolName: "Bash", toolInput: { command: pick(SHELL) } };
  const [toolName, toolInput] = pick(OTHER);
  return { toolName, toolInput };
}

function serializeScan(scan: any) {
  return { groups: scan.groups.map((g: Set<string>) => [...g].sort()), complete: scan.complete };
}

// ── what the human said ─────────────────────────────────────────────────────
function wordsOf(scan: any): string[][] {
  return scan.groups.map((g: Set<string>) => [...g]);
}
function userSaidFor(scan: any): string[] {
  const groups = wordsOf(scan);
  const r = rng();
  if (r < 0.14) return [];
  const naming = (gs: string[][]) => gs.map((g) => pick(g)).join(" and ");
  const variants: Array<() => string[]> = [
    () => [`please clean up ${naming(groups)}`],
    () => [`only touch ${naming(groups.slice(0, 1))}`],
    () => ["fix the failing tests"],
    () => [`${naming(groups)}`.toUpperCase() + " — DO IT"],
    () => ["Lösche bitte den Ordner", `ΣΊΣΥΦΟΣ ${naming(groups.slice(-1))}`],
    () => ["first message about something else", `then: remove ${naming(groups)}`, "go ahead"],
    () => ["yes"],
    () => [`${naming(groups.slice(1))} is fine to change`],
    () => ["İstanbul DELETE THE İNDEX", "ok"],
  ];
  return pick(variants)();
}
function agentMessageFor(scan: any): string | null {
  if (chance(0.5)) return null;
  const groups = wordsOf(scan);
  return pick([
    `I will remove ${groups.map((g) => pick(g)).join(", ")} next.`,
    "Shall I continue with the plan?",
    `Next step: ${groups.slice(0, 1).map((g) => pick(g)).join("")} only.`,
    "",
  ]);
}

// ── answers ─────────────────────────────────────────────────────────────────
function answersFor(policies: any[], intent: "v0" | "v1"): Record<string, number> {
  const a: Record<string, number> = {};
  const lean = pick(["high", "high", "any", "low"] as const);
  for (const p of policies) {
    for (const probe of p.probes) if (chance(0.93)) a[`${p.name}.${probe.id}`] = value(lean);
    if (p.exempt && chance(0.85)) a[`${p.name}.exempt`] = value(chance(0.7) ? "low" : "any");
    if (intent === "v0" && chance(0.8)) a[`${p.name}.user_asked`] = value(chance(0.5) ? "high" : "any");
  }
  if (chance(0.85)) a.injection = value(chance(0.75) ? "low" : "any");
  if (intent === "v0") {
    if (chance(0.75)) a.scope = value(chance(0.6) ? "high" : "any");
  } else {
    if (chance(0.85)) a.task_step = value(chance(0.5) ? "high" : "any");
    if (chance(0.85)) a.op_requested = value(chance(0.5) ? "high" : "any");
    if (chance(0.85)) a.beyond_task = value(pick(["low", "any", "high"] as const));
  }
  for (const k of Object.keys(a)) a[k] = fix(a[k]);
  return a;
}

// ── decide cases ────────────────────────────────────────────────────────────
function runDecide(c: any): any {
  const selected = c.policies.map((n: string) => POLICIES.get(n));
  const v =
    c.intentMode === "v1"
      ? decideV1(selected, c.answers, c.toolInput, c.userSaid, c.agentLastMessage, { userSaidCut: c.userSaidCut })
      : decide(selected, c.answers, c.toolInput, c.userSaid, DEFAULT_THRESHOLDS, c.userSaidCut);
  return JSON.parse(JSON.stringify(v));
}

const cases: any[] = [];
function addCase(c: any) {
  const scan = scanTargets(c.toolInput);
  const full = { id: `d-${String(cases.length + 1).padStart(4, "0")}`, ...c, targetScan: serializeScan(scan) };
  full.expected = runDecide(full);
  cases.push(full);
}

